       .consent-form {
         display: grid;
         gap: 1.25rem;
       }

       .form-field {
         display: grid;
         grid-template-columns: auto 1fr;
         gap: 0.85rem;
         align-items: start;
         padding: 1rem;
         border: 1px solid var(--border);
         border-radius: 16px;
         background: #fbfdff;
       }

       input[type="checkbox"] {
         width: 1.2rem;
         height: 1.2rem;
         margin: 0.15rem 0 0;
         accent-color: var(--accent);
         cursor: pointer;
       }

       label {
         display: block;
         font-weight: 700;
         line-height: 1.35;
       }

       .helper-text {
         grid-column: 2;
         margin: -0.45rem 0 0;
         color: var(--muted);
         font-size: 0.93rem;
         line-height: 1.45;
       }

       button {
         width: 100%;
         border: 0;
         border-radius: 14px;
         padding: 0.95rem 1.1rem;
         background: var(--accent);
         color: #ffffff;
         font: inherit;
         font-weight: 800;
         cursor: pointer;
         box-shadow: 0 12px 24px rgba(37, 99, 235, 0.22);
         transition:
           background 160ms ease,
           transform 160ms ease,
           box-shadow 160ms ease;
       }

       button:hover {
         background: var(--accent-dark);
         box-shadow: 0 14px 28px rgba(37, 99, 235, 0.28);
         transform: translateY(-1px);
       }

       button:focus-visible,
       input[type="checkbox"]:focus-visible {
         outline: 3px solid rgba(37, 99, 235, 0.28);
         outline-offset: 3px;
       }
     </style>
   </head>
   <body>
     <main id="root" class="app-shell"></main>

     <script>
       function ConsentCheckbox() {
         return `
           <div class="form-field">
             <input id="terms-consent" name="termsConsent" type="checkbox" required />
             <label for="terms-consent">I agree to the terms of use</label>
             <p class="helper-text">Required to create your account and continue.</p>
           </div>
         `;
       }

       function ConsentForm() {
         return `
           <section class="consent-card" aria-labelledby="form-title">
             <p class="eyebrow">Account setup</p>
             <h1 id="form-title">Review and accept</h1>
             <p class="intro">
               Confirm your consent to the terms of use before submitting the form.
             </p>
             <form class="consent-form" action="#" method="post">
               ${ConsentCheckbox()}
               <button type="submit">Submit consent</button>
             </form>
           </section>
         `;
       }

       function App() {
         return ConsentForm();
       }

       document.getElementById("root").innerHTML = App();
     </script>
   </body>
 </html>

